record.field:
activity_type_ids = env['ir.model.data'].search([
    ('module', '=', 'fmcg_business_automation'),
    ('model', '=', 'mail.activity.type'),
]).mapped('res_id')

pickings = env['stock.picking'].search([
    ('state', 'not in', ['done', 'cancel']),
], limit=50, order='create_date asc, id asc')

for picking in pickings:
    activity = env['mail.activity'].search([
        ('res_model', '=', 'stock.picking'),
        ('res_id', '=', picking.id),
        ('activity_type_id', 'in', activity_type_ids),
    ], order='create_date desc, id desc', limit=1)

    if not activity:
        raise UserError(
            'Picking %s (state: %s) chưa hoàn tất nhưng không có Activity để xử lý.'
            % (picking.name, picking.state)
        )

    activity.action_feedback()
